#define RING_BYTES_PER_PKT	0xEF

void InitRingFI(void)
{
	struct RingFsmUserDataStru *user_data = (struct RingFsmUserDataStru *)NEW(sizeof(struct RingFsmUserDataStru));
	user_data->dwTotal = sizeof(incoming_call_data);
	user_data->dwSent = 0;
	user_data->ringdata	= incoming_call_data;
	g_ring_fsminst = FsmInstNew(user_data, ring_inst_name);
	g_ring_fsminst->fsm = FsmNew(ring_fsm_function_list, RING_FSM_FUNC_COUNT, RING_FSM_STATE_COUNT, RING_FSM_EVENT_COUNT,RingFsmDefault);
}

void RingStart(struct FsmInst *fi, UCHAR event, void *arg)
{
	unsigned char param_len = 2;
	unsigned char *param = NEW(param_len);
	unsigned char ocf = 0x39;
	bse_log_api(TAG, "RingStart\r\n");
	param[0] = 0x01;
	param[1] = 0xA0;
	app_gap_vendor_command(MAKEWORD(ocf,param[0]),param,param_len);
	FREE(param);
}

void RingStarted(struct FsmInst *fi, UCHAR event, void *arg)
{
	bse_log_api(TAG, "RingStarted\r\n");
	FsmChangeState(fi, ST_RING_PLAYING);
	FsmEvent(g_ring_fsminst,EV_RING_PLAY,0);
}

void RingStop(struct FsmInst *fi, UCHAR event, void *arg)
{
	unsigned char param_len = 2;
	unsigned char *param = NEW(param_len);
	unsigned char ocf = 0x39;
	bse_log_api(TAG, "RingStop\r\n");
	param[0] = 0x00;
	param[1] = 0x06;
	app_gap_vendor_command(MAKEWORD(ocf,param[0]),param,param_len);
	FREE(param);
}

void RingStoped(struct FsmInst *fi, UCHAR event, void *arg)
{
	bse_log_api(TAG, "RingStoped\r\n");
	FsmChangeState(fi, ST_RING_IDLE);
	RING_FI_USER_DATA->dwSent = 0;
}

void RingPlay(struct FsmInst *fi, UCHAR event, void *arg)
{
	unsigned char param_len;
	unsigned char *param;
	unsigned char ocf = 0x66;
	if(RING_FI_USER_DATA->dwSent == 0) {	//First
		bse_log_info(TAG, "RingPlay First\r\n");
		param_len = 2+RING_BYTES_PER_PKT;
		param = NEW(param_len);
		param[0] = 0;
		param[1] = RING_BYTES_PER_PKT;
		memcpy(param+2,incoming_call_data,RING_BYTES_PER_PKT);
		RING_FI_USER_DATA->dwSent += RING_BYTES_PER_PKT;
	} else if(RING_FI_USER_DATA->dwTotal - RING_FI_USER_DATA->dwSent > RING_BYTES_PER_PKT) { //Continue
		bse_log_info(TAG, "RingPlay Continue\r\n");
		param_len = 2+RING_BYTES_PER_PKT;
		param = NEW(param_len);
		param[0] = 1;
		param[1] = RING_BYTES_PER_PKT;
		memcpy(param+2,incoming_call_data+RING_FI_USER_DATA->dwSent,RING_BYTES_PER_PKT);
		RING_FI_USER_DATA->dwSent += RING_BYTES_PER_PKT;
	} else { //Last
		bse_log_info(TAG, "RingPlay Last\r\n");
		param_len = 2+RING_FI_USER_DATA->dwTotal - RING_FI_USER_DATA->dwSent;
		param = NEW(param_len);
		param[0] = 2;
		param[1] = RING_FI_USER_DATA->dwTotal - RING_FI_USER_DATA->dwSent;
		memcpy(param+2,incoming_call_data+RING_FI_USER_DATA->dwSent,RING_FI_USER_DATA->dwTotal - RING_FI_USER_DATA->dwSent);
		RING_FI_USER_DATA->dwSent += (RING_FI_USER_DATA->dwTotal - RING_FI_USER_DATA->dwSent);
	}
	app_gap_vendor_command(MAKEWORD(ocf,param[0]),param,param_len);
	FREE(param);
}

void RingEnd(struct FsmInst *fi, UCHAR event, void *arg)
{
	bse_log_api(TAG, "RingEnd\r\n");
	RING_FI_USER_DATA->dwSent = 0;
	FsmChangeState(fi, ST_RING_IDLE);
}

void RingFsmDefault(struct FsmInst *fi, UCHAR event, void *arg)
{
}

